1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.ArrayList;
4	import java.util.List;
5	
6	import jakarta.validation.Valid;
7	import net.officefloor.plugin.variable.Out;
8	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
9	import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;
10	import org.springframework.validation.annotation.Validated;
11	import org.springframework.web.bind.annotation.RequestBody;
12	
13	/**
14	 * First step of {@code POST /api/owners}. Rejects a create whose firstName, lastName,
15	 * address, city or telephone is missing or blank with a 400 whose {@code errors} array
16	 * names each offending field. Bean validation still runs first (via {@code @Valid}) so
17	 * pattern/size failures keep their existing behaviour; this step additionally catches
18	 * whitespace-only values that slip past {@code @Size(min = 1)}. The {@code address} is
19	 * checked in its normalized form (see {@link AddressNormalizer}), so a value blank after
20	 * normalization is rejected too. Publishes the validated body for {@link BuildOwner}.
21	 */
22	@Validated
23	public class ValidateOwnerFields {
24	
25	    public void service(@Valid @RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
26	            throws MissingOwnerFieldsException {
27	        List<String> missing = new ArrayList<>();
28	        requireText(missing, "firstName", request.getFirstName());
29	        requireText(missing, "lastName", request.getLastName());
30	        requireText(missing, "address", AddressNormalizer.normalize(request.getAddress()));
31	        requireText(missing, "city", request.getCity());
32	        requireText(missing, "telephone", request.getTelephone());
33	        if (!missing.isEmpty()) {
34	            throw new MissingOwnerFieldsException(missing);
35	        }
36	        validated.set(request);
37	    }
38	
39	    private static void requireText(List<String> missing, String field, String value) {
40	        if (value == null || value.isBlank()) {
41	            missing.add(field);
42	        }
43	    }
44	}
