6	/**
7	 * Normalizes the create-owner {@code address} into its canonical form (see
8	 * {@link AddressNormalizer}) and writes it back onto the body so {@link BuildOwner} maps and
9	 * {@link SaveOwner} stores the normalized value, and {@code GET} returns it. Running before
10	 * {@link AssignHousehold} means that step sees — and therefore compares and hashes — the
11	 * normalized address.
12	 *
13	 * <p>Runs after {@link ValidateOwnerFields} (which rejects an address blank after
14	 * normalization) and mutates the validated body in place — {@code @Val} yields the same object
15	 * the earlier step published.
16	 */
17	public class NormalizeOwnerAddress {
18	
19	    public void service(@Val OwnerFieldsDto request) {
20	        request.setAddress(AddressNormalizer.normalize(request.getAddress()));
21	    }
22	}
