1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	import net.officefloor.plugin.variable.Val;
8	import org.springframework.samples.petclinic.model.Owner;
9	
10	/**
11	 * Assigns the owner's <em>deterministic</em> {@code householdId}: the first 12 hex characters
12	 * of SHA-256 over {@code normalizedLastName + '|' + postcode}. Because the value is derived
13	 * purely from the last name and postcode, every owner sharing those two fields computes the
14	 * <em>same</em> identifier automatically — no cross-owner lookup and no back-fill are needed.
15	 *
16	 * <p>This is why {@code sharesHousehold} no longer <em>creates</em> the household link: the link
17	 * exists by construction. The flag only tells the later duplicate checks to admit a second owner
18	 * of the same household as a declared member (see {@link CheckOwnerIdentityUnique}).
19	 *
20	 * <p>Runs after {@link BuildOwner} (so the entity — hence its last name and postcode — exists)
21	 * and before {@link CheckOwnerIdentityUnique}, mutating the built {@link Owner} in place.
22	 */
23	public class AssignHousehold {
24	
25	    public void service(@Val Owner built) {
26	        String lastName = normalize(built.getLastName());
27	        String postcode = built.getPostcode() == null ? "" : built.getPostcode();
28	        built.setHouseholdId(householdId(lastName, postcode));
29	    }
30	
31	    /** A stable household identifier: first 12 hex chars of SHA-256 over the normalized last
32	     *  name and postcode, so all members of the same household derive the same value. */
33	    static String householdId(String normalizedLastName, String postcode) {
34	        try {
35	            byte[] digest = MessageDigest.getInstance("SHA-256")
36	                    .digest((normalizedLastName + "|" + postcode).getBytes(StandardCharsets.UTF_8));
37	            StringBuilder sb = new StringBuilder(digest.length * 2);
38	            for (byte b : digest) {
39	                sb.append(String.format("%02x", b));
40	            }
41	            return sb.substring(0, 12);
42	        }
43	        catch (NoSuchAlgorithmException e) {
44	            throw new IllegalStateException("SHA-256 not available", e);
45	        }
46	    }
47	
48	    /** Lower-case, trim, and collapse internal whitespace runs to a single space. */
49	    private static String normalize(String value) {
50	        if (value == null) {
51	            return "";
52	        }
53	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
54	    }
55	}
