1	package org.springframework.samples.petclinic.mapper;
2	
3	import java.util.Map;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	
7	/**
8	 * Derives an owner's locality (canonical region). Locality now flows from the owner's
9	 * region-and-hash {@code customerCode}: the REGION prefix of {@code '<REGION>-<HASH8>'} is the
10	 * canonical region, so locality and the identity always agree. When the customerCode has not been
11	 * assigned it falls back to deriving the region directly. In that direct derivation the postcode is
12	 * preferred: a 4-digit postcode falling in a known region's range (NSW 2000-2099, VIC 3000-3099,
13	 * QLD 4000-4099) fixes the region, which disambiguates cities that share a name; only when the
14	 * postcode is absent or in no known range does it fall back to the fixed city-to-region table.
15	 * Kept out of {@link OwnerMapper} so MapStruct does not mistake the helper for an implicit mapping
16	 * method and apply it to every string property.
17	 */
18	public final class Locality {
19	
20	    /** City -> canonical region; anything not listed derives locality "UNKNOWN". */
21	    private static final Map<String, String> CITY_REGION = Map.of(
22	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
23	
24	    /** Region -> inclusive 4-digit postcode range {low, high}. */
25	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
26	        "NSW", new int[] {2000, 2099},
27	        "VIC", new int[] {3000, 3099},
28	        "QLD", new int[] {4000, 4099});
29	
30	    private Locality() {
31	    }
32	
33	    /**
34	     * The owner's locality, read from the REGION prefix of its region-and-hash customerCode so it
35	     * agrees with the identity. Falls back to deriving the region from the city and postcode when
36	     * the customerCode has not been assigned (e.g. records that never went through create).
37	     */
38	    public static String of(Owner owner) {
39	        String code = owner.getCustomerCode();
40	        if (code != null) {
41	            int dash = code.lastIndexOf('-');
42	            if (dash > 0) {
43	                return code.substring(0, dash);
44	            }
45	        }
46	        return of(owner.getCity(), owner.getPostcode());
47	    }
48	
49	    /**
50	     * The canonical region, preferring the postcode range and falling back to the
51	     * city-to-region table. Returns "UNKNOWN" when neither resolves a region.
52	     */
53	    public static String of(String city, String postcode) {
54	        String byPostcode = regionForPostcode(postcode);
55	        return byPostcode != null ? byPostcode : of(city);
56	    }
57	
58	    /** The canonical region for {@code city}, or "UNKNOWN" when it is not in the table. */
59	    public static String of(String city) {
60	        return city == null ? "UNKNOWN" : CITY_REGION.getOrDefault(city, "UNKNOWN");
61	    }
62	
63	    /**
64	     * The region whose range contains {@code postcode}, or {@code null} when the postcode
65	     * is absent, non-numeric, or in no known range.
66	     */
67	    private static String regionForPostcode(String postcode) {
68	        if (postcode == null || postcode.isBlank()) {
69	            return null;
70	        }
71	        int value;
72	        try {
73	            value = Integer.parseInt(postcode.trim());
74	        }
75	        catch (NumberFormatException ex) {
76	            return null;
77	        }
78	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
79	            int[] range = entry.getValue();
80	            if (value >= range[0] && value <= range[1]) {
81	                return entry.getKey();
82	            }
83	        }
84	        return null;
85	    }
86	}
