1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Flags a soft (non-hard) duplicate: a <em>suspected</em>, undeclared duplicate across
9	 * households. By the time this step runs the request has already passed
10	 * {@link CheckOwnerIdentityUnique}, so it is neither a full-identity nor an (undeclared)
11	 * household duplicate. This step records a weaker signal: an existing owner that shares this
12	 * owner's {@code lastName} (compared case-insensitively) and {@code postcode} but has a
13	 * <em>different</em> telephone <em>and a different {@code householdId}</em>. Such an owner is
14	 * still created, but with {@code possibleDuplicate = true} and {@code possibleDuplicateOf} set
15	 * to the matching owner's id (the lowest matching id when several match). When nothing matches,
16	 * {@code possibleDuplicate} is {@code false} and {@code possibleDuplicateOf} stays absent.
17	 *
18	 * <p>Because {@code householdId} is now computed from last name and postcode, any owner that
19	 * shares both with an existing one is in the <em>same</em> household. Such a pairing is handled
20	 * by the household-duplicate block (rejected, or admitted as a declared member): a declared
21	 * member is not a suspected duplicate, so the same-household exclusion keeps it unflagged.
22	 *
23	 * <p>Runs after {@link CheckOwnerIdentityUnique} and before {@link SaveOwner} (so the new
24	 * owner is not yet among {@code findAll()} and cannot match itself), mutating the built
25	 * {@link Owner} in place.
26	 */
27	public class CheckPossibleDuplicate {
28	
29	    public void service(@Val Owner built, OwnerRepository ownerRepository) {
30	        Integer matchId = null;
31	        for (Owner existing : ownerRepository.findAll()) {
32	            if (sameLastName(built, existing) && samePostcode(built, existing)
33	                    && differentTelephone(built, existing) && differentHousehold(built, existing)) {
34	                Integer id = existing.getId();
35	                if (id != null && (matchId == null || id < matchId)) {
36	                    matchId = id;
37	                }
38	            }
39	        }
40	        built.setPossibleDuplicate(matchId != null);
41	        built.setPossibleDuplicateOf(matchId);
42	    }
43	
44	    private static boolean sameLastName(Owner a, Owner b) {
45	        return normalize(a.getLastName()).equals(normalize(b.getLastName()));
46	    }
47	
48	    private static boolean samePostcode(Owner a, Owner b) {
49	        String pa = a.getPostcode();
50	        String pb = b.getPostcode();
51	        return pa != null && !pa.isBlank() && pa.equals(pb);
52	    }
53	
54	    private static boolean differentTelephone(Owner a, Owner b) {
55	        String ta = a.getTelephone();
56	        String tb = b.getTelephone();
57	        return ta == null ? tb != null : !ta.equals(tb);
58	    }
59	
60	    /** A declared household member (same computed householdId) is not a suspected duplicate. */
61	    private static boolean differentHousehold(Owner a, Owner b) {
62	        String ha = a.getHouseholdId();
63	        return ha == null || !ha.equals(b.getHouseholdId());
64	    }
65	
66	    private static String normalize(String value) {
67	        return value == null ? "" : value.trim().toLowerCase();
68	    }
69	}
