7	/**
8	 * Derives the read-time {@code householdSize} on an owner: the number of owners that share its
9	 * {@code householdId} (the SHA-256 of last name + postcode assigned by {@link AssignHousehold}),
10	 * counting the owner itself. Owners with no {@code householdId} are a household of one.
11	 *
12	 * <p>This backs the household factor of the membership points system (a household of 3 or more
13	 * adds points, see {@link org.springframework.samples.petclinic.mapper.Membership}). Runs before
14	 * the responder so the size is carried onto the returned DTO, mirroring
15	 * {@link MarkBulkSignupWarning}.
16	 */
17	public class CountHouseholdMembers {
18	
19	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
20	        String householdId = owner.getHouseholdId();
21	        if (householdId == null) {
22	            owner.setHouseholdSize(1);
23	            return;
24	        }
25	        int count = 0;
26	        for (Owner existing : ownerRepository.findAll()) {
27	            if (householdId.equals(existing.getHouseholdId())) {
28	                count++;
29	            }
30	        }
31	        owner.setHouseholdSize(count);
32	    }
33	}
