3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.mapper.IdentityKey;
5	import org.springframework.samples.petclinic.model.Owner;
6	import org.springframework.samples.petclinic.repository.OwnerRepository;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;
9	
10	/**
11	 * Rejects a create-owner request that duplicates an existing owner. Two rules are folded here,
12	 * both keyed off the now-computed {@code householdId} (SHA-256 of last name + postcode, see
13	 * {@link AssignHousehold}):
14	 *
15	 * <ol>
16	 * <li><b>Identity match</b> — the derived {@code identityKey}
17	 * ({@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}, see
18	 * {@link IdentityKey}) exactly equals an existing owner's. This expresses the former telephone
19	 * and email duplicate checks. It fires regardless of {@code sharesHousehold}, so a full
20	 * duplicate that opts in is still a 409.</li>
21	 * <li><b>Household duplicate</b> — an existing owner shares this owner's {@code householdId}
22	 * (i.e. the same last name and postcode). Because the household is keyed on those fields, a
23	 * second such owner is the same household and is rejected — <em>unless</em> the request sets
24	 * {@code sharesHousehold}, which admits it as a declared household member.</li>
25	 * </ol>
26	 *
27	 * <p>Runs after {@link AssignHousehold} (so the built owner's householdId is settled) and
28	 * before {@link CheckPossibleDuplicate}/{@link SaveOwner} (so the new owner is not yet among
29	 * {@code findAll()}). On a match raises {@link DuplicateIdentityException} (409).
30	 */
31	public class CheckOwnerIdentityUnique {
32	
33	    public void service(@Val Owner built, @Val OwnerFieldsDto request, OwnerRepository ownerRepository)
34	            throws DuplicateIdentityException {
35	        String identityKey = IdentityKey.of(built);
36	        boolean sharesHousehold = Boolean.TRUE.equals(request.getSharesHousehold());
37	        String householdId = built.getHouseholdId();
38	        for (Owner existing : ownerRepository.findAll()) {
39	            if (identityKey.equals(IdentityKey.of(existing))) {
40	                throw new DuplicateIdentityException(identityKey);
41	            }
42	            if (!sharesHousehold && householdId != null
43	                    && householdId.equals(existing.getHouseholdId())) {
44	                throw new DuplicateIdentityException(identityKey);
45	            }
46	        }
47	    }
48	}
